/** The top EXP Multi reference for a class — base merged with its profile. */
export function topExpFlatForClass(classKey: string | null | undefined): FlatMap {
  const profile = classKey ? TOP_EXP_CLASS_PROFILE[classKey] : undefined;
  const override = profile ? TOP_EXP_PROFILE_OVERRIDES[profile] : undefined;
  return override ? { ...TOP_EXP_FLAT, ...override } : TOP_EXP_FLAT;
}
